func HasEntry() predicate.DictionaryRelation {
	return predicate.DictionaryRelation(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, EntryTable, EntryColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasEntryWith applies the HasEdge predicate on the "entry" edge with a given conditions (other predicates).
func HasEntryWith(preds ...predicate.DictionaryEntry) predicate.DictionaryRelation {
	return predicate.DictionaryRelation(func(s *sql.Selector) {
		step := newEntryStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.DictionaryRelation) predicate.DictionaryRelation {
	return predicate.DictionaryRelation(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.DictionaryRelation) predicate.DictionaryRelation {
	return predicate.DictionaryRelation(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.DictionaryRelation) predicate.DictionaryRelation {
	return predicate.DictionaryRelation(sql.NotPredicates(p))
}
